1	// Package payflow implements payment intent settlement and reconciliation.
2	package payflow
3	
4	import (
5		"fmt"
6		"math"
7		"sort"
8	)
9	
10	// Intent is one payment request from an account abstraction wallet.
11	type Intent struct {
12		ID        string
13		Account   string
14		Paymaster string
15		Amount    int64
16		Asset     string
17		Nonce     uint64
18		State     string
19	}
20	
21	// Settlement is the ledger effect of executing an intent.
22	type Settlement struct {
23		Intent  string
24		Charged int64
25		FeeBps  int
26		Ref     string
27		Status  string
28		Reason  string
29	}
30	
31	// Execute applies fee policy and enforces per-intent idempotency.
32	//
33	// 判断顺序保持旧接口约定：非 pending 状态、已结算编号优先于本次金额检查。
34	// 金额必须为正、费率必须在 [0,10000] 基点内；手续费按
35	// amount*feeBps/10000 向下取整（使用与账本一致的溢出安全算法，乘积中间值
36	// 不会溢出），扣款总额为金额加手续费。金额或费率不合法、总额超出 int64
37	// 时一律 rejected 且不扣款、不留结算引用、不占用编号；总额可表示但余额
38	// 不足时 failed；只有成功才标记编号。
39	func Execute(intent Intent, feeBps int, spent map[string]bool, balance int64) Settlement {
40		if intent.State != "pending" {
41			return Settlement{Intent: intent.ID, Status: "rejected", Reason: "intent is not pending"}
42		}
43		if spent[intent.ID] {
44			return Settlement{Intent: intent.ID, Status: "rejected", Reason: "duplicate settlement attempt"}
45		}
46		if intent.Amount <= 0 {
47			return Settlement{Intent: intent.ID, Status: "rejected", Reason: reasonBadAmount}
48		}
49		if feeBps < 0 || feeBps > 10000 {
50			return Settlement{
51				Intent: intent.ID,
52				Status: "rejected",
53				Reason: fmt.Sprintf("fee_bps must be within [0,10000], got %d", feeBps),
54			}
55		}
56		fee := feeFor(intent.Amount, feeBps)
57		if fee > math.MaxInt64-intent.Amount {
58			return Settlement{Intent: intent.ID, Status: "rejected", Reason: reasonOverflow}
59		}
60		total := intent.Amount + fee
61		if total > balance {
62			return Settlement{Intent: intent.ID, Status: "failed", Reason: "insufficient balance for amount plus fee"}
63		}
64		spent[intent.ID] = true
65		return Settlement{Intent: intent.ID, Charged: total, FeeBps: feeBps, Ref: "settle:" + intent.ID, Status: "settled"}
66	}
67	
68	// Reconcile reports intents with no matching settlement, in stable order.
69	func Reconcile(intents []Intent, settlements []Settlement) []string {
70		seen := map[string]bool{}
71		for _, settlement := range settlements {
72			if settlement.Status == "settled" {
73				seen[settlement.Intent] = true
74			}
75		}
76		var gaps []string
77		for _, intent := range intents {
78			if !seen[intent.ID] {
79				gaps = append(gaps, intent.ID)
80			}
81		}
82		sort.Strings(gaps)
83		return gaps
84	}
