927	// cloneState 返回账本状态的独立深拷贝，供预览在副本上模拟而不触碰真实状态。
928	func cloneState(st *ledgerState) *ledgerState {
929		cp := &ledgerState{
930			Version:     st.Version,
931			Initial:     make(map[balanceKey]int64, len(st.Initial)),
932			Balances:    make(map[balanceKey]int64, len(st.Balances)),
933			Settlements: append([]Record(nil), st.Settlements...),
934			Refunds:     append([]RefundRecord(nil), st.Refunds...),
935		}
936		for k, v := range st.Initial {
937			cp.Initial[k] = v
938		}
939		for k, v := range st.Balances {
940			cp.Balances[k] = v
941		}
942		return cp
943	}
