956	// validateRefundRequest 校验一项退款请求：退款编号、原付款编号、原因三者
957	// 都必须非空，校验顺序即对外约定（id → settlement_id → reason）。
958	// 未通过校验的编号不占用退款资格，之后可修改后重新提交。
959	func validateRefundRequest(req *RefundRequest) (string, bool) {
960		if req.ID == "" {
961			return reasonEmptyRefundID, false
962		}
963		if req.SettlementID == "" {
964			return reasonEmptySettlement, false
965		}
966		if req.Reason == "" {
967			return reasonEmptyReason, false
968		}
969		return "", true
970	}
971	
972	// attachRefundDetail 把一笔成功退款（首次成功或幂等重复携带的同一条原记录）
973	// 的统一详情填入逐项结果：原付款编号、账户、资产、退款总额、原因与完整退款
974	// 记录。首次成功与重复申请共用这一个出口，保证两者拼装出的详情逐字一致。
975	func attachRefundDetail(res *RefundResult, rec RefundRecord) {
976		res.Reason = rec.Reason
977		res.SettlementID = rec.SettlementID
978		res.Account = rec.Account
979		res.Asset = rec.Asset
980		res.Charged = rec.Charged
981		cp := rec
982		res.Record = &cp
983	}
984	
985	// judgeRefund 按退款规则评估一项请求，只读取状态 st，不产生任何副作用。
986	// 返回逐项结果；预计成功时结果只填编号，落账效果以 ledgerEffect 描述，
987	// 由调用方交给生效策略落地。判定顺序即对外约定：参数校验、已成功退款编号
988	// 的重复/冲突（优先于目标判断，即使新目标不存在也不退化成 not_found）、
989	// 目标结算存在性、目标是否已被其他退款编号退回。
990	func judgeRefund(req *RefundRequest, st *ledgerState) (RefundResult, *ledgerEffect) {
991		res := RefundResult{ID: req.ID}
992	
993		// 1. 参数校验。未通过的编号不占用退款资格。
994		if reason, ok := validateRefundRequest(req); !ok {
995			res.Status = StatusInvalid
996			res.Reason = reason
997			return res, nil
998		}
999	
1000		// 2. 已成功退款编号优先判定：目标与原因都相同则幂等返回原退款记录；
1001		//    任一不同则冲突（即使新目标不存在也不能退化成 not_found）。
1002		//    两者都不再入账。本批次内先成功的同编号项也在此被看到。
1003		if prior, exists := findRefundIn(st.Refunds, req.ID); exists {
1004			if prior.SettlementID == req.SettlementID && prior.Reason == req.Reason {
1005				res.Status = StatusDuplicate
1006				attachRefundDetail(&res, prior)
1007			} else {
1008				res.Status = StatusConflict
1009				res.Reason = reasonRefundConflict
1010			}
1011			return res, nil
1012		}
1013	
1014		// 3. 新退款编号：目标必须是一笔成功结算（原付款只曾失败也算不存在）。
1015		target, exists := findRecordIn(st.Settlements, req.SettlementID)
1016		if !exists {
1017			res.Status = StatusNotFound
1018			res.Reason = fmt.Sprintf(reasonSettlementGone, req.SettlementID)
1019			return res, nil
1020		}
1021	
1022		// 4. 每笔原付款最多退回一次：已被其他退款编号退回则报告已退款，不加余额。
1023		if prior, refunded := findRefundOfSettlementIn(st.Refunds, req.SettlementID); refunded {
1024			res.Status = StatusAlreadyRefunded
1025			res.Reason = fmt.Sprintf(reasonAlreadyRefunded, req.SettlementID, prior.ID)
1026			return res, nil
1027		}
1028	
1029		// 5. 预计成功：全额（amount 与当时手续费一并，即以原结算的 charged 为准）
1030		//    退回原账户、原资产；序号按当前退款历史长度连续递增。
1031		rec := RefundRecord{
1032			ID:           req.ID,
1033			SettlementID: target.ID,
1034			Reason:       req.Reason,
1035			Account:      target.Account,
1036			Asset:        target.Asset,
1037			Amount:       target.Amount,
1038			Fee:          target.Fee,
1039			Charged:      target.Charged,
1040			AfterSeq:     int64(len(st.Settlements)),
1041			Seq:          int64(len(st.Refunds)) + 1,
1042		}
1043		return res, &ledgerEffect{
1044			key:    balanceKey{target.Account, target.Asset},
1045			delta:  target.Charged,
1046			refund: &rec,
1047		}
1048	}
1049	
1050	// runRefundBatch 按输入顺序在给定状态 st 上处理整个退款批次，返回逐项结果。
1051	// 退款规则（judgeRefund）与落账生效（commit）分离：规则只读取 st 给出判定
1052	// 和预计落账效果，不改动任何状态；生效策略与付款提交共用同一套
1053	// applyEffect/落盘/回滚步骤——真实提交先改内存再原子落盘、失败回滚并报告
1054	// storage_error。保存失败时 commit 已回滚该项（余额与退款历史恢复原样），
1055	// 该项不占退款编号、不把原付款标成已退款，前项成功保留、后项继续处理。
1056	// 调用方必须持有 reg.mu。
1057	func runRefundBatch(batch RefundBatch, st *ledgerState, commit commitEffect) []RefundResult {
1058		out := make([]RefundResult, 0, len(batch.Refunds))
1059		for i := range batch.Refunds {
1060			req := &batch.Refunds[i]
1061	
1062			// 1. 规则判定：纯读取，不产生任何副作用。
1063			res, eff := judgeRefund(req, st)
1064			if eff == nil {
1065				out = append(out, res)
1066				continue
1067			}
1068	
1069			// 2. 生效：保存失败时 commit 已回滚该项（余额与历史恢复原样），
1070			//    该项报告 storage_error，不留退款记录、不占退款序号，后项继续。
1071			if err := commit(st, *eff); err != nil {
1072				res.Status = StatusStorage
1073				res.Reason = err.Error()
1074				out = append(out, res)
1075				continue
1076			}
1077	
1078			// 3. 成功落账：与重复申请一样通过统一出口拼装详情。
1079			res.Status = StatusRefundSuccess
1080			attachRefundDetail(&res, *eff.refund)
1081			out = append(out, res)
1082		}
1083		return out
1084	}
1085	
1086	// findRefundIn 在给定退款历史中按编号查找成功记录。
1087	func findRefundIn(refunds []RefundRecord, id string) (RefundRecord, bool) {
1088		// 退款按成功顺序追加且 ID 唯一；单机账本量级直接扫描。
1089		for _, r := range refunds {
1090			if r.ID == id {
1091				return r, true
1092			}
1093		}
1094		return RefundRecord{}, false
1095	}
