1097	// findRefundOfSettlementIn 返回退回指定结算的那笔退款（每笔结算最多一笔）。
1098	func findRefundOfSettlementIn(refunds []RefundRecord, settlementID string) (RefundRecord, bool) {
1099		for _, r := range refunds {
1100			if r.SettlementID == settlementID {
1101				return r, true
1102			}
1103		}
1104		return RefundRecord{}, false
1105	}
1106	
1107	// Refund 按输入顺序处理一个退款批次。各项独立处理：后项能看到前项成功退回的
1108	// 余额；任一项失败不影响其余项（存储错误只回滚出错项本身，前项保留，后项继续）。
1109	// 结果与输入逐项对应，空批次返回空结果。
1110	//
1111	// 语义：
1112	//   - 参数合法时，已成功的退款编号优先判定：目标结算与原因都相同返回 duplicate
1113	//     及原退款记录（不再入账）；任一不同返回 conflict（即使新目标不存在也一样，
1114	//     不能退化成 not_found）。
1115	//   - 新退款编号：找不到成功结算（含原付款只曾失败）返回 not_found；
1116	//     该结算已被其他退款编号退回返回 already_refunded，不增加余额。
1117	//   - 成功时把原记录的 charged（含当时已扣手续费）全额退回原账户、原资产；
1118	//     退款金额与去向完全由原结算确定，原结算记录及其编号、顺序保持不变。
1119	//   - 失败申请（参数错误、目标不存在、已退款、冲突、存储错误）不占用退款编号，
1120	//     之后可修改原因或目标再提交。
1121	func (l *Ledger) Refund(batch RefundBatch) (*RefundBatchResult, error) {
1122		if err := l.beginOp(); err != nil {
1123			return nil, err
1124		}
1125		defer l.endOp()
1126	
1127		l.reg.mu.Lock()
1128		defer l.reg.mu.Unlock()
1129	
1130		results := runRefundBatch(batch, l.reg.state, l.persistEffect)
1131		return &RefundBatchResult{Results: results}, nil
1132	}
1133	
1134	func (l *Ledger) stateView() *ledgerState { return l.reg.state }
