1146	// Query 返回余额视图（按账户、资产排序，保证确定性）与按成功先后排列的记录。
1147	func (l *Ledger) Query() (*Snapshot, error) {
1148		if err := l.beginOp(); err != nil {
1149			return nil, err
1150		}
1151		defer l.endOp()
1152		l.reg.mu.Lock()
1153		defer l.reg.mu.Unlock()
1154	
1155		st := l.stateView()
1156		bals := make([]BalanceView, 0, len(st.Balances))
1157		for k, v := range st.Balances {
1158			bals = append(bals, BalanceView{Account: k.account, Asset: k.asset, Balance: v})
1159		}
1160		sortBalances(bals)
1161		recs := make([]Record, len(st.Settlements))
1162		copy(recs, st.Settlements)
1163		refunds := make([]RefundRecord, len(st.Refunds))
1164		copy(refunds, st.Refunds)
1165		return &Snapshot{Balances: bals, Settlements: recs, Refunds: refunds}, nil
1166	}
1167	
1168	// Balance 返回单个 (账户, 资产) 组合的余额；组合不存在按 0 处理。
1169	func (l *Ledger) Balance(account, asset string) (int64, error) {
1170		if err := l.beginOp(); err != nil {
1171			return 0, err
1172		}
1173		defer l.endOp()
1174		l.reg.mu.Lock()
1175		defer l.reg.mu.Unlock()
1176		return l.stateView().Balances[balanceKey{account, asset}], nil
1177	}
1178	
1179	func sortBalances(bals []BalanceView) {
1180		sort.Slice(bals, func(i, j int) bool {
1181			if bals[i].Account != bals[j].Account {
1182				return bals[i].Account < bals[j].Account
1183			}
1184			return bals[i].Asset < bals[j].Asset
1185		})
1186	}
1187	
1188	// persistLocked 将当前状态原子写入磁盘；调用方必须持有 reg.mu。
1189	func (l *Ledger) persistLocked() error {
1190		if l.reg.failHook != nil && l.reg.failHook.FailNextPersist() {
1191			return ledgerError(ErrStorage, "injected write failure")
1192		}
1193		return atomicWrite(l.path, l.stateView())
1194	}
1195	
1196	// SetFailHook 为该路径的账本安装存储故障注入，仅用于测试。
1197	func SetFailHook(l *Ledger, fw FailWriter) {
1198		l.reg.failHook = fw
1199	}
